    h, w = len(grid), len(grid[0])
    # The color-coded bars each contain a gap. Connect every gap vertically
    # toward the nearest other bar/edge, retaining the bar's color.
    bars = []
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c-1] and row[c+1]:
                bars.append((r, c, row[c-1]))
    # For each gap, extend in both directions until reaching another colored
    # cell. The generated lines form the crossings demonstrated by the task.
